package gitpublish

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

type Mode string

const (
	ModeOff           Mode = "off"
	ModeCommit        Mode = "commit"
	ModeCommitAndPush Mode = "commit-and-push"
)

type Policy struct {
	Mode        Mode
	Remote      string
	PushTimeout time.Duration
}

type Request struct {
	Root     string
	Paths    []string
	All      bool
	Message  string
	Identity string
}

type Result struct {
	Repository string `json:"repository"`
	Branch     string `json:"branch"`
	Commit     string `json:"commit,omitempty"`
	Remote     string `json:"remote,omitempty"`
	Committed  bool   `json:"committed"`
	Pushed     bool   `json:"pushed"`
	Skipped    bool   `json:"skipped"`
}

type Publisher interface {
	Publish(context.Context, Request) (Result, error)
}

type CommandPublisher struct {
	policy Policy
}

func New(policy Policy) CommandPublisher {
	if policy.Mode == "" {
		policy.Mode = ModeOff
	}
	if strings.TrimSpace(policy.Remote) == "" {
		policy.Remote = "origin"
	}
	if policy.PushTimeout <= 0 {
		policy.PushTimeout = 2 * time.Minute
	}
	return CommandPublisher{policy: policy}
}

func (p CommandPublisher) Publish(ctx context.Context, req Request) (Result, error) {
	if p.policy.Mode == ModeOff {
		return Result{Skipped: true}, nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	root := filepath.Clean(strings.TrimSpace(req.Root))
	if root == "" || root == "." {
		return Result{}, fmt.Errorf("git publish: repository root is required")
	}
	repo, err := gitOutput(ctx, root, nil, "rev-parse", "--show-toplevel")
	if err != nil {
		return Result{}, fmt.Errorf("git publish: resolve repository from %s: %w", root, err)
	}
	repo, err = filepath.Abs(strings.TrimSpace(repo))
	if err != nil {
		return Result{}, fmt.Errorf("git publish: resolve repository path: %w", err)
	}
	branch, err := gitOutput(ctx, repo, nil, "branch", "--show-current")
	if err != nil {
		return Result{}, fmt.Errorf("git publish: resolve branch: %w", err)
	}
	branch = strings.TrimSpace(branch)
	if branch == "" {
		return Result{}, fmt.Errorf("git publish: detached HEAD is not supported")
	}
	result := Result{Repository: repo, Branch: branch}
	paths, err := publishPaths(repo, req.Paths, req.All)
	if err != nil {
		return result, err
	}
	common, err := gitOutput(ctx, repo, nil, "rev-parse", "--git-common-dir")
	if err != nil {
		return result, fmt.Errorf("git publish: resolve common directory: %w", err)
	}
	common = strings.TrimSpace(common)
	if !filepath.IsAbs(common) {
		common = filepath.Join(repo, common)
	}
	common, err = filepath.Abs(filepath.Clean(common))
	if err != nil {
		return result, fmt.Errorf("git publish: resolve common directory path: %w", err)
	}
	lock, err := acquireLock(ctx, filepath.Join(common, "ultraplan-publish.lock"))
	if err != nil {
		return result, fmt.Errorf("git publish: acquire repository lock: %w", err)
	}
	defer lock.release()

	if len(paths) > 0 {
		commit, committed, commitErr := commitPaths(ctx, repo, common, paths, req.Message, req.Identity)
		result.Commit, result.Committed = commit, committed
		if commitErr != nil {
			return result, commitErr
		}
	}
	if result.Commit == "" {
		result.Commit, err = gitOutput(ctx, repo, nil, "rev-parse", "HEAD")
		if err != nil {
			return result, fmt.Errorf("git publish: resolve HEAD: %w", err)
		}
		result.Commit = strings.TrimSpace(result.Commit)
	}
	if p.policy.Mode != ModeCommitAndPush {
		return result, nil
	}
	if !validRemoteName(p.policy.Remote) {
		return result, fmt.Errorf("git publish: invalid remote name %q", p.policy.Remote)
	}
	pushCtx, cancel := context.WithTimeout(ctx, p.policy.PushTimeout)
	defer cancel()
	upstreamRemote, upstreamErr := gitOutput(pushCtx, repo, nil, "for-each-ref", "--format=%(upstream:remotename)", "refs/heads/"+branch)
	if upstreamErr != nil {
		return result, fmt.Errorf("git publish: resolve upstream: %w", upstreamErr)
	}
	upstreamRemote = strings.TrimSpace(upstreamRemote)
	if upstreamRemote != "" {
		if !validRemoteName(upstreamRemote) {
			return result, fmt.Errorf("git publish: invalid upstream remote name %q", upstreamRemote)
		}
		upstreamRef, refErr := gitOutput(pushCtx, repo, nil, "for-each-ref", "--format=%(upstream:remoteref)", "refs/heads/"+branch)
		if refErr != nil || strings.TrimSpace(upstreamRef) == "" {
			return result, fmt.Errorf("git publish: resolve upstream ref: %w", refErr)
		}
		result.Remote = upstreamRemote
		_, err = gitOutput(pushCtx, repo, nil, "push", "--porcelain", "--", upstreamRemote, "HEAD:"+strings.TrimSpace(upstreamRef))
	} else {
		result.Remote = p.policy.Remote
		_, err = gitOutput(pushCtx, repo, nil, "push", "--porcelain", "--set-upstream", "--", p.policy.Remote, "HEAD:refs/heads/"+branch)
	}
	if err != nil {
		if errors.Is(pushCtx.Err(), context.DeadlineExceeded) {
			return result, fmt.Errorf("git publish: push timed out after %s: %w", p.policy.PushTimeout, pushCtx.Err())
		}
		return result, fmt.Errorf("git publish: push %s/%s: %w", result.Remote, branch, err)
	}
	result.Pushed = true
	return result, nil
}

func publishPaths(repo string, requested []string, all bool) ([]string, error) {
	if all {
		return []string{"."}, nil
	}
	set := map[string]bool{}
	for _, raw := range requested {
		if strings.TrimSpace(raw) == "" {
			continue
		}
		path := filepath.Clean(raw)
		if !filepath.IsAbs(path) {
			path = filepath.Join(repo, path)
		}
		path, err := filepath.Abs(path)
		if err != nil {
			return nil, fmt.Errorf("git publish: resolve path %q: %w", raw, err)
		}
		rel, err := filepath.Rel(repo, path)
		if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			return nil, fmt.Errorf("git publish: path %q escapes repository %s", raw, repo)
		}
		set[filepath.ToSlash(rel)] = true
	}
	paths := make([]string, 0, len(set))
	for path := range set {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	return paths, nil
}

func commitPaths(ctx context.Context, repo, common string, paths []string, message, identity string) (string, bool, error) {
	message = strings.TrimSpace(message)
	if message == "" {
		return "", false, fmt.Errorf("git publish: commit message is required")
	}
	if identity != "" {
		message += "\n\nUltraPlan-Publication: " + strings.TrimSpace(identity)
	}
	parent, err := gitOutput(ctx, repo, nil, "rev-parse", "HEAD")
	if err != nil {
		return "", false, fmt.Errorf("git publish: resolve commit parent: %w", err)
	}
	parent = strings.TrimSpace(parent)
	temp, err := os.CreateTemp(common, "ultraplan-index-*")
	if err != nil {
		return "", false, fmt.Errorf("git publish: create temporary index: %w", err)
	}
	indexPath := temp.Name()
	if closeErr := temp.Close(); closeErr != nil {
		_ = os.Remove(indexPath)
		return "", false, fmt.Errorf("git publish: close temporary index: %w", closeErr)
	}
	_ = os.Remove(indexPath)
	defer os.Remove(indexPath)
	env := []string{"GIT_INDEX_FILE=" + indexPath}
	if _, err := gitOutput(ctx, repo, env, "read-tree", parent); err != nil {
		return "", false, fmt.Errorf("git publish: seed temporary index: %w", err)
	}
	args := append([]string{"add", "-A", "--"}, paths...)
	if _, err := gitOutput(ctx, repo, env, args...); err != nil {
		return "", false, fmt.Errorf("git publish: stage owned paths: %w", err)
	}
	tree, err := gitOutput(ctx, repo, env, "write-tree")
	if err != nil {
		return "", false, fmt.Errorf("git publish: write tree: %w", err)
	}
	tree = strings.TrimSpace(tree)
	parentTree, err := gitOutput(ctx, repo, nil, "rev-parse", parent+"^{tree}")
	if err != nil {
		return "", false, fmt.Errorf("git publish: resolve parent tree: %w", err)
	}
	if tree == strings.TrimSpace(parentTree) {
		return parent, false, nil
	}
	commit, err := gitInput(ctx, repo, env, message+"\n", "commit-tree", tree, "-p", parent)
	if err != nil {
		return "", false, fmt.Errorf("git publish: create commit: %w", err)
	}
	commit = strings.TrimSpace(commit)
	ref, err := gitOutput(ctx, repo, nil, "symbolic-ref", "-q", "HEAD")
	if err != nil || strings.TrimSpace(ref) == "" {
		return "", false, fmt.Errorf("git publish: resolve branch ref: %w", err)
	}
	if _, err := gitOutput(ctx, repo, nil, "update-ref", strings.TrimSpace(ref), commit, parent); err != nil {
		return "", false, fmt.Errorf("git publish: branch changed while committing: %w", err)
	}
	resetArgs := append([]string{"reset", "-q", "HEAD", "--"}, paths...)
	if _, err := gitOutput(ctx, repo, nil, resetArgs...); err != nil {
		return commit, true, fmt.Errorf("git publish: reconcile index after commit: %w", err)
	}
	return commit, true, nil
}

func gitOutput(ctx context.Context, dir string, extraEnv []string, args ...string) (string, error) {
	return gitInput(ctx, dir, extraEnv, "", args...)
}

func gitInput(ctx context.Context, dir string, extraEnv []string, input string, args ...string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", append([]string{"-C", dir}, args...)...)
	cmd.Env = gitEnvironment(extraEnv)
	if input != "" {
		cmd.Stdin = strings.NewReader(input)
	}
	output, err := cmd.CombinedOutput()
	if err != nil {
		detail := strings.TrimSpace(string(output))
		if detail == "" {
			detail = err.Error()
		}
		return "", fmt.Errorf("git %s: %s", strings.Join(args, " "), detail)
	}
	return strings.TrimSpace(string(output)), nil
}

func gitEnvironment(extra []string) []string {
	overrides := map[string]string{"GIT_TERMINAL_PROMPT": "0", "LC_ALL": "C"}
	for _, item := range extra {
		if key, value, ok := strings.Cut(item, "="); ok {
			overrides[key] = value
		}
	}
	env := make([]string, 0, len(os.Environ())+len(overrides))
	for _, item := range os.Environ() {
		key, _, _ := strings.Cut(item, "=")
		if _, replaced := overrides[key]; !replaced {
			env = append(env, item)
		}
	}
	for key, value := range overrides {
		env = append(env, key+"="+value)
	}
	return env
}

func validRemoteName(name string) bool {
	if name == "" || strings.HasPrefix(name, "-") {
		return false
	}
	for _, r := range name {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || strings.ContainsRune("._/-", r) {
			continue
		}
		return false
	}
	return true
}

package app

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
)

type durableOperationManager struct {
	repository runcontrol.Repository
	owner      runcontrol.Owner
	mu         sync.Mutex
	owned      map[string]*ownedDurableOperation
}

type ownedDurableOperation struct {
	fence        runcontrol.Fence
	cancel       context.CancelFunc
	stop         chan struct{}
	done         chan struct{}
	eventMu      sync.Mutex
	progressKey  string
	progressAt   time.Time
	omitted      uint64
	omittedFirst time.Time
	omittedLast  time.Time
}

// durableCLICommand is the synchronous CLI counterpart to the web/TUI
// acceptance boundary. It keeps the manager alive for the whole command and
// gives product code the cancellation-aware context owned by the durable run.
type durableCLICommand struct {
	manager  *durableOperationManager
	accepted AcceptedOperation
}

type durableOperationContextKey struct{}

type durableOperationOwnership struct {
	repository runcontrol.Repository
	fence      runcontrol.Fence
}

func beginDurableCLICommand(deps dependencies, request OperationRequest) (*durableCLICommand, error) {
	repository, _, err := runRepository(deps)
	if err != nil {
		return nil, err
	}
	manager := newDurableOperationManager(repository, deps.runControl.owner)
	accepted, err := manager.AcceptOperation(deps.ctx, Confirmation{Request: request}, "")
	if err != nil {
		return nil, classifiedCause(ExitRuntime, err, "run-control.accept")
	}
	return &durableCLICommand{manager: manager, accepted: accepted}, nil
}

func (c *durableCLICommand) Context() context.Context { return c.accepted.Context }

func (c *durableCLICommand) QAWriterToken() (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	if c == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is unavailable")
	}
	return qaOwnershipFromContext(c.accepted.Context)
}

func (c *durableCLICommand) Finish(runErr error) error {
	state := OperationComplete
	if c.accepted.Context.Err() != nil {
		state = OperationCancelled
	} else if runErr != nil {
		state = OperationFailed
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := c.manager.FinishOperation(ctx, c.accepted.RunID, state, runErr); err != nil {
		return classifiedCause(ExitRuntime, err, "run-control.finish")
	}
	return nil
}

func finishDurableCLICommand(command *durableCLICommand, runErr error) error {
	if command == nil {
		return runErr
	}
	return errors.Join(runErr, command.Finish(runErr))
}

func newDurableOperationManager(repository runcontrol.Repository, owner runcontrol.Owner) *durableOperationManager {
	return &durableOperationManager{repository: repository, owner: owner, owned: make(map[string]*ownedDurableOperation)}
}

func (m *durableOperationManager) AcceptOperation(ctx context.Context, confirmation Confirmation, digest string) (AcceptedOperation, error) {
	req := confirmation.Request
	target := runcontrol.Target{
		Kind: "operation", Operation: string(req.Kind), Project: req.Project, Sprint: req.Sprint,
		Study: req.Study, Stage: req.Stage, Task: req.Task,
	}
	snapshot, err := m.repository.Accept(ctx, runcontrol.Acceptance{
		Target: target, ProductStatus: "prepared", OperationAlias: digest, ConfirmationDigest: digest,
	})
	if err != nil && digest != "" && errors.Is(err, runcontrol.ErrConflict) {
		existing, resolveErr := m.repository.ResolveOperationAlias(ctx, digest)
		if resolveErr != nil {
			return AcceptedOperation{}, errors.Join(err, resolveErr)
		}
		return AcceptedOperation{RunID: string(existing.RunID), Context: ctx, Existing: true, Lifecycle: string(existing.Lifecycle)}, nil
	}
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation acceptance: %w", err)
	}
	attempt, _, err := m.repository.Claim(ctx, runcontrol.Claim{RunID: snapshot.RunID, Owner: m.owner, Lease: runcontrol.OwnerLeaseDuration})
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation owner claim: %w", err)
	}
	fence := runcontrol.Fence{RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: m.owner.ID, FencingGeneration: attempt.FencingGeneration}
	if _, _, err := appendRunEventWithRetry(ctx, m.repository, fence, runcontrol.EventDraft{
		Type: runcontrol.EventLifecycle, Lifecycle: runcontrol.LifecycleRunning,
		Payload: map[string]string{"lifecycle": string(runcontrol.LifecycleRunning)},
	}); err != nil {
		terminalCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, _ = proposeRunTerminalWithRetry(terminalCtx, m.repository, fence, runcontrol.TerminalProposal{Outcome: runcontrol.TerminalPersistenceLost, Reason: "operation start persistence failed", ProposedBy: m.owner.ID})
		cancel()
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation start: %w", err)
	}
	operationCtx, cancel := context.WithCancel(runcontrol.WithParentRun(ctx, snapshot.RunID))
	operationCtx = context.WithValue(operationCtx, durableOperationContextKey{}, durableOperationOwnership{repository: m.repository, fence: fence})
	owned := &ownedDurableOperation{fence: fence, cancel: cancel, stop: make(chan struct{}), done: make(chan struct{})}
	m.mu.Lock()
	m.owned[string(snapshot.RunID)] = owned
	m.mu.Unlock()
	go m.controlOperation(operationCtx, owned)
	return AcceptedOperation{RunID: string(snapshot.RunID), Context: operationCtx, Lifecycle: string(runcontrol.LifecycleRunning)}, nil
}

func qaOwnershipFromContext(ctx context.Context) (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	ownership, ok := ctx.Value(durableOperationContextKey{}).(durableOperationOwnership)
	if !ok || ownership.repository == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is missing from the operation context")
	}
	token := sprint.QAWriterToken{RunID: string(ownership.fence.RunID), OperationalAttemptID: string(ownership.fence.AttemptID), FencingGeneration: ownership.fence.FencingGeneration}
	fence := func(got sprint.QAWriterToken) error {
		if got != token {
			return runcontrol.ErrStaleFence
		}
		fenceCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer cancel()
		_, err := ownership.repository.Heartbeat(fenceCtx, ownership.fence, runControlLease)
		return err
	}
	return token, fence, nil
}

func (m *durableOperationManager) RecordOperationEvent(ctx context.Context, runID string, event OperationEvent) (bool, error) {
	m.mu.Lock()
	owned := m.owned[runID]
	m.mu.Unlock()
	if owned == nil {
		return false, runcontrol.ErrNotFound
	}
	owned.eventMu.Lock()
	defer owned.eventMu.Unlock()
	eventType := runcontrol.EventProgress
	if event.State == OperationFailed {
		eventType = runcontrol.EventWarning
	}
	key := string(eventType) + "\x00" + event.Stage + "\x00" + event.Task + "\x00" + event.PhaseState + "\x00" + event.SafeSummary + "\x00" + event.EventType + "\x00" + event.EventKind + "\x00" + event.Tool + "\x00" + event.Reason + "\x00" + event.Detail
	now := time.Now().UTC()
	elapsed := now.Sub(owned.progressAt)
	if eventType == runcontrol.EventProgress && key == owned.progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
		if owned.omitted == 0 {
			owned.omittedFirst = now
		}
		owned.omitted++
		owned.omittedLast = now
		return false, nil
	}
	payload := map[string]string{
		"state": string(event.State), "type": event.EventType,
		"count": fmt.Sprintf("%d/%d", event.Completed, event.Total),
	}
	for key, value := range map[string]string{
		"phase_state": event.PhaseState, "summary": event.SafeSummary,
		"tool_call_id": event.ToolCallID, "tool_status": event.ToolStatus,
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"provider": event.Provider, "model": event.Model, "harness": event.Harness,
	} {
		if value != "" {
			payload[key] = value
		}
	}
	var omission *runcontrol.Omission
	if event.Message != "" {
		omission = &runcontrol.Omission{Reason: "presentation message omitted", Count: 1}
	}
	if owned.omitted > 0 {
		if omission == nil {
			omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
		}
		omission.Count += owned.omitted
		omission.FirstAt, omission.LastAt = &owned.omittedFirst, &owned.omittedLast
		owned.omitted = 0
	}
	_, _, err := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeOperation, Stage: event.Stage, Task: event.Task,
		Kind: event.EventKind, Tool: event.Tool, Action: event.Action, Reason: event.Reason,
		Detail: event.Detail, Payload: payload, Omission: omission,
	})
	if err != nil {
		owned.cancel()
		return false, err
	}
	if eventType == runcontrol.EventProgress {
		owned.progressKey, owned.progressAt = key, now
	}
	return true, nil
}

func (m *durableOperationManager) controlOperation(ctx context.Context, owned *ownedDurableOperation) {
	defer close(owned.done)
	ticker := time.NewTicker(runcontrol.OwnerTickInterval)
	defer ticker.Stop()
	lastHeartbeat, lastReconcile := time.Now(), time.Now()
	for {
		select {
		case <-ctx.Done():
			return
		case <-owned.stop:
			return
		case now := <-ticker.C:
			snapshot, err := m.repository.Snapshot(ctx, owned.fence.RunID)
			if err != nil {
				owned.cancel()
				return
			}
			if snapshot.Cancellation.State == runcontrol.CancellationRequested {
				if _, _, err := m.repository.AcknowledgeCancellation(ctx, owned.fence); err != nil {
					owned.cancel()
					return
				}
				owned.cancel()
				return
			}
			if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
				if _, err := m.repository.Heartbeat(ctx, owned.fence, runcontrol.OwnerLeaseDuration); err != nil {
					owned.cancel()
					return
				}
				lastHeartbeat = now
			}
			if now.Sub(lastReconcile) >= runcontrol.ReconciliationInterval {
				if _, err := m.repository.Reconcile(ctx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
					owned.cancel()
					return
				}
				lastReconcile = now
			}
		}
	}
}

func (m *durableOperationManager) FinishOperation(ctx context.Context, runID string, state OperationState, runErr error) error {
	m.mu.Lock()
	owned := m.owned[runID]
	delete(m.owned, runID)
	m.mu.Unlock()
	if owned == nil {
		return nil
	}
	owned.eventMu.Lock()
	if owned.omitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{Type: runcontrol.EventOmission, Omission: &runcontrol.Omission{Reason: "equivalent progress coalesced", Count: owned.omitted, FirstAt: &owned.omittedFirst, LastAt: &owned.omittedLast}})
		if appendErr != nil && runErr == nil {
			runErr = appendErr
		}
		owned.omitted = 0
	}
	owned.eventMu.Unlock()
	close(owned.stop)
	<-owned.done
	owned.cancel()
	outcome := runcontrol.TerminalSucceeded
	reason := "operation completed"
	switch {
	case errors.Is(runErr, context.DeadlineExceeded):
		outcome, reason = runcontrol.TerminalTimedOut, "operation deadline exceeded"
	case errors.Is(runErr, context.Canceled), state == OperationCancelled:
		outcome, reason = runcontrol.TerminalCancelled, "operation cancelled"
	case runErr != nil, state == OperationFailed:
		outcome, reason = runcontrol.TerminalFailed, "operation failed"
	case state == OperationPartial:
		outcome, reason = runcontrol.TerminalInterrupted, "operation interrupted"
	}
	_, _, err := proposeRunTerminalWithRetry(ctx, m.repository, owned.fence, runcontrol.TerminalProposal{Outcome: outcome, Reason: reason, ProposedBy: m.owner.ID})
	return err
}

