	}
	state, loadErr := LoadExecuteRunState(root, sp)
	if loadErr != nil {
		t.Fatal(loadErr)
	}
	if state.Tasks[0].Status != ExecuteTaskFailed || len(state.Tasks[0].Diagnostics) == 0 || state.Tasks[0].Diagnostics[len(state.Tasks[0].Diagnostics)-1].Code != "state-save-failed" {
